LANG_NAMES = dict(en='английский', es='испанский', pt='португальский', fr='французский', de='немецкий', ru='русский', ja='японский', hi='хинди')


def topic_for(now):
    local = now.astimezone(__import__('zoneinfo').ZoneInfo('Europe/Kyiv'))
    return (local.date().toordinal() * 6 + max(0, (local.hour - 10)//2)) % len(TOPICS)


def channel_language(video):
    snip = video['snippet']
    code = snip.get('channelLanguage') or snip.get('defaultAudioLanguage') or snip.get('defaultLanguage')
    if not code:
        return 'не указан'
    root = code.split('-')[0]
    label = LANG_NAMES.get(root, code)
    return label + (' (по языку ролика)' if not snip.get('channelLanguage') else '')


def render_card(index, evidence, now):
    name, _, ideas, approach, difficulty = TOPICS[index]
    lines = [f'💡 Ниша: {name}', '', '🎬 Как вести без лица', approach,
             '', 'Что снять первым:']
    lines += [f'{i}. {title}' for i, title in enumerate(ideas, 1)]
    lines += ['', 'Почему стоит попробовать',
              f'Свежие успешные видео найдены у {len(evidence)} разных каналов. Можно протестировать собственную серию по этой теме.',
              '', 'С чего начать', 'Подготовь три ролика по 12–20 минут с собственными сценариями.',
              '', '📺 Каналы и примеры']
    for rate, video, lang, base, subscribers in evidence:
        snip = video['snippet']
        views = int(video['statistics'].get('viewCount', 0))
        lines += [f"\n{snip['channelTitle'][:65]}",
                  f"Язык: {channel_language(video)}",
                  f"Канал: https://www.youtube.com/channel/{snip['channelId']}",
                  f"Пример: https://www.youtube.com/watch?v={video['id']}",
                  f"{views:,} просмотров · опубликовано {snip['publishedAt'][:10]}"]
    lines += ['', 'Подача без лица — предложенный вариант; отсутствие автора в примерах ещё не проверено. Монетизацию проверь вручную.']
    return '\n'.join(lines)
